    /**
     * Manager for implementing causal analysis type 
     * 
     * [1] Average Causal Effect
     * [2] Core Analysis
     * [3] Intervention Analysis
     * [4] Root Causal Analysis
     * [5] Counterfactual Analysis
     * [6] Outlier Roote Cause Analysis
     */
    class CausalAnalysisManager {
        constructor() {
            this._strategies = []
        }
        /**
         * @param {any} strategy
         */
        addStrategy(strategy) {
            this._strategies = [...this._strategies, strategy]
        }
        /**
         * 
         * @returns 
         */
        getStrategy(name) {
            return this._strategies.find(strategy => strategy._name === name)
        }
        // history functionality
    }

    class CausalAnalysisStrategy {
        constructor(name, handlers) {
            this._name = name
            this._handlers = handlers
        }
        /**
         * Builds pane container 
         */
        build_container() {
            console.log("retrieving handler for building container")
            console.log(this._handlers)
            this._handlers["build_container"]()
        }
        prepare_request() {
            return this._handlers["prepare_request"]()
        }
        fetch(req_object) {
            return this._handlers["fetch"](req_object)
        }
        postprocess(req_object = null) {
            if (req_object === null) {
                return this._handlers["postprocess"]()
            }
            return this._handlers["postprocess"](req_object)
        }
    }

    function show(type, bringToFront) {
        if (bringToFront !== false) {
            RED.sidebar.show("help");
        }
    }

    function addCollider(path_info, collider_id) {
        let { path_type, set, path_index } = path_info
        if (colliders[collider_id]) {
            let prev_state = colliders[collider_id];
            let new_fd = [...prev_state[path_type]]
            new_fd.push(path_index)
            let new_state = { ...prev_state, [path_type]: new_fd }
            colliders = { ...colliders, [collider_id]: new_state }
        } else {
            if (path_type === "back") {
                colliders = { ...colliders, [collider_id]: { "back": [path_index], "front": [] } }
            } else {
                colliders = { ...colliders, [collider_id]: { "back": [], "front": [path_index] } }
            }
        }
        return
    }

