    /**
     * 
     * @returns 
     */
    async function getPyWhyLinkInfo() {
        // console.log("===========causeway.getPyWhyLinkInfo===========")
        if (activeWorkspace === 0) {
            return {}
        } else {
            if (pywhy_results[activeWorkspace]) {
                await processPyWhyResult(pywhy_results[activeWorkspace], false, activeWorkspace)
                return pywhy_results[activeWorkspace]
            } else {
                // prepare match statement that retrieves each causal path
                await $.ajax({
                    headers: {
                        Accept: "text/html",
                        // "Accept-Language": lang,
                    },
                    cache: false,
                    url: "causeway/getPyWhyInfo",
                    type: "POST",
                    data: {
                        server: window.location.hostname + ":1729",
                        "activeWorkspace": activeWorkspace,
                    },
                    success: async function (res) {
                        if (nodes === null || nodes === undefined) {
                            await loadNodes()
                        }
                        pywhy_results[activeWorkspace] = await processPyWhyResult(res, true, activeWorkspace)
                    },
                }).done(() => {
                    // console.log("pywhy_result", pywhy_results[activeWorkspace])
                }).fail((exception) => {
                    console.log(exception)
                    console.log("failed")
                    pywhy_results[activeWorkspace] = {}
                })
                // console.log(pywhy_results[activeWorkspace])
                return pywhy_results[activeWorkspace]
            }
        }

    }

