    /**
     * Prepares which attributes must be included for model/causal analysis based in the input property of each node
     * @returns 
     */
    async function loadLabels() {
        model_id = parentNode.id
        console.log("model name: ", parentNode.label)
        // [v]:Entity Node Id ; [vt]: Knowledge Graph Id
        let data_graphs = {}
        if (nodes !== null) {
            nodes.forEach(node => {
                if (node.name !== undefined) {
                    if (node.props) {
                        node.props.forEach(prop => {
                            if (prop.p === "input") {
                                // check if the knowledge graph type exists in the current graph labels; 
                                if (!data_graphs[prop.vt]) {
                                    // console.log("knowledge graph type does not exist ", prop.vt, RED.nodes.workspace(prop.vt).label)
                                    let type_init = { [prop.v]: [{ [prop.attribute]: node.name }] }
                                    data_graphs = { ...data_graphs, [prop.vt]: type_init }
                                } else {

                                    // grab the already seen set of nodes pertaining to that knowledge graph
                                    let kg_nodes = data_graphs[prop.vt]
                                    // type exists in graph labeler
                                    if (kg_nodes[prop.v]) {
                                        // console.log("EXISTS ", prop.v, node.name)
                                        let type_add = kg_nodes[prop.v]
                                        type_add.push({ [prop.attribute]: node.name })
                                        kg_nodes = { ...kg_nodes, [prop.v]: type_add }
                                        data_graphs = { ...data_graphs, [prop.vt]: kg_nodes }
                                    } else {
                                        // type does not exists
                                        data_graphs = { ...data_graphs, [prop.vt]: { ...data_graphs[prop.vt], [prop.v]: [{ [prop.attribute]: node.name }] } }
                                    }
                                }
                            }
                        })
                    }
                }
            });
            Object.keys(data_graphs).forEach(key => {
                let parent = RED.nodes.workspace(key)
                if (parent) {
                    _labels[parent.label] = { "relations": {}, "entities": {} }
                    if (data_graphs[key]) {
                        Object.keys(data_graphs[key]).forEach(node_key => {
                            let node = RED.nodes.node(node_key)
                            if (node !== null) {
                                if (node.type === "relation") {
                                    _labels[parent.label]["relations"][node.name] = data_graphs[key][node_key]
                                }
                                if (node.type === "entity") {
                                    _labels[parent.label]["entities"][node.name] = data_graphs[key][node_key]
                                }
                            }
                        })

                    }
                }
            })
        }
        return _labels
    }

