    /**
     * Handler for outputting dowhy results 
     * @param {*} res The response containg results from dowhy analysis from causal api server
     */
    async function dowhy_postprocess(res) {
        console.log("dowhy postprocess response ", res)
        res.json().then(json => {
            try {
                console.log("json response ", json)
                let estimandConsole = $("#estimand-console")
                let estimateConsole = $("#estimate-console")
                estimandConsole.empty();
                estimateConsole.empty();
                if (json["dowhy"]["estimand"]) {
                    Object.keys(json["dowhy"]["estimand"]).forEach(key => {
                        console.log(key, json["dowhy"]["estimand"][key])
                        let div = createSubContainer()

                        $("<label>", {
                            text: key,
                            style: {
                                "margin-left": "10px",
                                "margin-right": "10px",
                            }
                        }).appendTo(div).css({
                            "width": "100%",
                            "font-weight": "bold"
                        })
                        $("<div/>", {
                            style: {
                                "margin-left": "10px",
                                "margin-right": "10px"
                            },
                        }).appendTo(div).text(json["dowhy"]["estimand"][key]);
                        div.appendTo(estimandConsole);
                    });
                }
                if (json["dowhy"]["estimator"]) {
                    Object.keys(json["dowhy"]["estimator"]).forEach(key => {
                        console.log(key, json["dowhy"]["estimator"][key])
                        let div = createSubContainer()
                        $("<label>", {
                            text: key,
                            style: {
                                "margin-left": "10px",
                                "margin-right": "10px",
                            }
                        }).appendTo(div).css({
                            "width": "100%",
                            "font-weight": "bold"
                        })
                        $("<div/>").appendTo(div).text(json["dowhy"]["estimator"][key]).css({
                            "overflow-wrap": "break-word",
                            "margin-left": "10px",
                            "margin-right": "10px",
                        })
                        div.appendTo(estimateConsole);
                    });

                    if (json["dowhy"]["stats"]) {
                        Object.keys(json["dowhy"]["stats"]).forEach(key => {
                            console.log(key, json["dowhy"]["stats"][key])
                            let div = createSubContainer()
                            $("<label>", {
                                text: key,
                                style: {
                                    "margin-left": "10px",
                                    "margin-right": "10px",

                                }
                            }).appendTo(div).css({
                                "width": "auto",
                                "font-weight": "bold"
                            })
                            $("<div/>", {
                                style: {
                                    "margin-left": "10px",
                                    "margin-right": "10px"
                                },
                            }).appendTo(div).text(json["dowhy"]["stats"][key]);
                            div.appendTo(estimateConsole);
                        })
                    }
                }

                // call typedb api to store causal analsyis instance
                // causal_analysis owns 1)uuid 2)timestamp 3)library 4)results 5)model_parameters
                json = JSON.stringify(json)
                let typedb_ca = {
                    "libraries": ["dowhy"],
                    "result": json,
                    "treatment": { "ca_treatment_name": $("#ca-treatment").val(), "ca_treatment_id": nn[$("#ca-treatment").val()] },
                    "outcome": { "ca_outcome_name": $("#ca-outcome").val(), "ca_outcome_id": nn[$("#ca-outcome").val()] },
                    "causal_model": { "cm_name": model_id, "cm_id": activeWorkspace },
                    "estimation_method": $("#est-methods").val()
                }
                storeCausalAnalysis(typedb_ca)

            } catch (exception) {
                console.log("received exception: ", exception)
                RED.notify(exception, "error")
                throw exception
            }
            RED.notify("[Causal Analysis] Displaying identified estimand and estimate", "success");
        })
    }

    /**
    * Update dictionary containing state of recent analyses performed. 
    * Keys consists of: distribution_samples, intervention_samples, counterfactual_samples, rootcausalanalysis, outliercauseanalysis
    * @param {string} type 
    * @param {object} pywhy_results 
    * @param {object} json 
    * @returns 
    */
    let update_pywhy_info = async (type, pywhy_results, json) => {
        console.log("updating pywhy dictionary for ", type, json)
        if (json.hasOwnProperty(type)) {
            if (type === "coreanalysis") {
                for await (let key of Object.keys(json[type])) {
                    json[type][key] = JSON.parse(json[type][key])
                    // parse node analysis
                    for await (let subkey of Object.keys(json[type][key])) {
                        json[type][key][subkey] = JSON.parse(json[type][key][subkey])
                    }
                }
            }
            if (type === "intervention") {
                console.log("UPDATING TYPE JSON ")
                let distr_exists = json[type].hasOwnProperty("distribution_samples")
                let intr_distr_exists = json[type].hasOwnProperty("intervention_samples")
                console.log(distr_exists)
                console.log(intr_distr_exists)
                if (distr_exists || intr_distr_exists) {
                    pywhy_results[type] = {}
                    if (distr_exists) {
                        pywhy_results[type]["distribution_samples"] = json[type]["distribution_samples"]
                    }
                    if (intr_distr_exists) {
                        pywhy_results[type]["intervention_samples"] = json[type]["intervention_samples"]
                    }
                }
            }
            pywhy_results = {
                ...pywhy_results,
                [type]: json[type]
            }
        }
        return pywhy_results
    }

