    // prepare data for graph ingestion -- isolate distributions pre and post intervention based on a certain variable
    const prepare_data = async (data, distr_type, variable, type) => {
        console.log("data ", data)
        console.log("distr type ", distr_type)
        console.log("variable ", variable)
        console.log("type: ", type)
        if (type === "rca") {
            if (typeof data[distr_type] === "string") {
                data[distr_type] = JSON.parse(data[distr_type])
            }
            let x_values = Object.values(data[distr_type][variable])
            return x_values
        }
        if (type === "intervention") {
            if (Object.keys(data[distr_type]).includes(variable)) {
                let x_values = Object.values(data[distr_type][variable])
                return x_values
            }
        }
        return []
    }

    const draw_distributions = (data, distr_types, svg_container, type, req_object) => {
        console.log("Data in draw distributions ", data)
        let config = {
            fill: (type, hovered = false) => {
                if (hovered) {
                    if (type === "distribution_samples") {
                        return "hsl(175, 75%, 25%, 0.5)"
                    }
                    if (type === "intervention_samples") {
                        return "hsl(301, 75%, 25%, 0.5)"
                    }
                }
                return type === "distribution_samples" ? "hsl(175, 75%, 25%, 0.25)" : "hsl(301, 75%, 25%, 0.25)"
            },
            stroke: (type) => {
                return type !== undefined ? type : "black"
            },
            circle: {
                cx: () => { return 20 },
                cy: (type) => {
                    return type === "distribution_samples" ? 10 : 30
                }
            },
            title: (type) => {
                return type === "distribution_samples" ? "Pre" : "Post"
            }
        }

        // svg: the container for the graphs ; data: array containg the values for plotting
        /**
         * 
         * @param {*} svg 
         * @param {*} data 
         * @param {*} distr_types 
         * @param {*} type 
         * @param {*} config 
         */
        const raincloud = (svg, data, distr_types, type, config, req_object) => {
            svg = d3.select('#distribution-graph-' + type)
            svg.style("margin-left", "2em")
            svg.call(curve, data, distr_types, type, config)
            // TR
            // svg = d3.select('#distribution-box-dots-' + type)
            // svg.call(dots, data, distr_types, type, config)
            // svg.call(boxplot, data, distr_types, type, config)
            svg = d3.select("#distribution-stats-" + type)
            svg.style("margin-left", "2em")
            svg.call(stats_summary, data, distr_types, type, config, req_object)
        }

        /**
         * 
         * @param {*} svg 
         * @param {*} data 
         * @param {*} distr_types 
         * @param {*} type 
         * @param {*} config 
         */
        const curve = (svg, data, distr_types, type, config) => {
            let min_x = d3.min(data[0])
            let max_x = d3.max(data[0])
            let histogram = ""
            let x = ""
            let y = ""
            console.log("minx: ", min_x)
            console.log("maxx: ", max_x)
            for (let type in distr_types) {
                if (d3.max(data[type]) > max_x) {
                    max_x = d3.max(data[type])
                }
                if (d3.min(data[type]) < min_x) {
                    min_x = d3.min(data[type])
                }
            }

            // https://bl.ocks.org/emmasaunders/f7178ed715a601c5b2c458a2c7093f78
            // https://bl.ocks.org/ptvans/c53fb28a9991a8c001ed
            for (let type in distr_types) {
                svg.append("circle").attr("cx", config.circle.cx()).attr("cy", config.circle.cy(distr_types[type])).attr("r", 6).style("fill", config.fill(distr_types[type]))
                svg.append("text").attr("x", config.circle.cx() + 20).attr("y", config.circle.cy(distr_types[type])).text(config.title(distr_types[type])).style("font-size", "14px").attr("alignment-baseline", "middle")


                var dataBar = d3.layout.histogram()
                    .bins(20)(data[type]);

                x = d3.scale.linear().range([0, width]).domain([min_x, max_x])
                y = d3.scale.linear().range([height, 0]).domain([0, d3.max(dataBar, function (d) { return d.length; })])

                // Bars
                var bars = svg.selectAll(distr_types[type])
                    .data(dataBar)
                    .enter()
                    .append('rect')
                    .attr('class', 'bar')
                    .attr('transform', function (d) {
                        return 'translate(' + x(d.x) + ',' + y(d.y) + ')';
                    })
                    .attr('x', 1)
                    .attr('width', function (d) {
                        console.log(x(d.dx) - x(0))
                        return (x(d.dx) - x(0)) <= 0 ? 0 : (x(d.dx) - x(0));
                    })
                    .attr('height', function (d) { return height - y(d.y); })
                    .attr("fill", config.fill(distr_types[type]))
                // .on("mouseover", function (event) {
                //     d3.select(d3.event.target)
                //         .attr("fill", config.fill(distr_types[type], true))
                // })
                // .on("mouseout", function (event) {
                //     d3.select(d3.event.target)
                //         .attr("fill", config.fill(distr_types[type], false))
                // })

            }


            x = d3.scale.linear().range([0, width]).domain([min_x, max_x])
            let axisLeft = d3.svg.axis().scale(y).orient("left")
            let axisRight = d3.svg.axis().scale(y).orient("right")
            let axisTop = d3.svg.axis().scale(x).orient("top")
            let axisBottom = d3.svg.axis().scale(x).orient("bottom")


            // X Axis
            svg.append('g')
                .attr('transform', 'translate(0,' + height + ')')
                .call(axisBottom).selectAll("text")
                .attr("y", 0)
                .attr("x", 9)
                .attr("dy", ".35em")
                .attr("transform", "rotate(90)")
                .style("text-anchor", "start");
        }

        /**
         * 
         * @param {*} svg 
         * @param {*} data 
         * @param {*} distr_types 
         * @param {*} type 
         * @param {*} config 
         */
        const dots = (svg, data, distr_types, type, config) => {
            let min_x = d3.min(data[0])
            let max_x = d3.max(data[0])
            let x = ""
            for (let type in distr_types) {
                if (d3.max(data[type]) > max_x) {
                    max_x = d3.max(data[type])
                }
                if (d3.min(data[type]) < min_x) {
                    min_x = d3.min(data[type])
                }
            }
            x = d3.scale.linear().range([0, width]).domain([min_x, max_x])

            for (let type in distr_types) {

                svg
                    .append('g')
                    .classed('dots', true)
                    .selectAll('circle')
                    .data(data[type])
                    .enter()
                    .append('circle')
                    .attr('r', 2)
                    .attr('cx', x)
                    .attr('cy', () => Math.random() * size * 0.5)
                    .style("fill", config.fill(distr_types[type]))
            }
        }

        /**
         * 
         * @param {*} svg 
         * @param {*} data 
         * @param {*} distr_types 
         * @param {*} type 
         * @param {*} config 
         */
        const boxplot = (svg, data, distr_types, type, config) => {

            let min_x = d3.min(data[0])
            let max_x = d3.max(data[0])
            let x = ""
            for (let type in distr_types) {
                if (d3.max(data[type]) > max_x) {
                    max_x = d3.max(data[type])
                }
                if (d3.min(data[type]) < min_x) {
                    min_x = d3.min(data[type])
                }
            }
            x = d3.scale.linear().range([0, width]).domain([min_x, max_x])

            const bar = grid * 2
            for (let type in distr_types) {
                let position = distr_types[type] === "distribution_samples" ? 0.25 : 0.5
                const plot = svg
                    .append('g')
                    .classed('boxplot', true)
                    .attr('transform', `translate(0,${200 * position})`)

                // vertical line
                plot
                    .append('line')
                    .attr('x1', x(d3.quantile(data[type], 0.5)))
                    .attr('x2', x(d3.quantile(data[type], 0.5)))
                    .attr('y1', 0)
                    .attr('y2', bar)
                    .attr("stroke", config.stroke())

                // lower quantile
                plot
                    .append('line')
                    .attr('x1', x(d3.quantile(data[type], 0.1)))
                    .attr('x2', x(d3.quantile(data[type], 0.25)))
                    .attr('y1', bar * 0.5)
                    .attr('y2', bar * 0.5)
                    .attr("stroke", config.stroke())
                // upper quantile
                plot
                    .append('line')
                    .attr('x1', x(d3.quantile(data[type], 0.9)))
                    .attr('x2', x(d3.quantile(data[type], 0.75)))
                    .attr('y1', bar * 0.5)
                    .attr('y2', bar * 0.5)
                    .attr("stroke", config.stroke())
                plot.append('rect')
                    .attr('x', x(d3.quantile(data[type], 0.25)))
                    .attr('y', 0)
                    .attr('height', bar)
                    .attr('width', x(d3.quantile(data[type], 0.75)) - x(d3.quantile(data[type], 0.25)))
                    .attr("fill-opacity", 0.7)
                    .attr("stroke", "black")
                    .attr("fill", config.fill(distr_types[type]))

            }
        }

        /**
         * 
         * @param {*} svg 
         * @param {*} data 
         * @param {*} distr_types 
         * @param {*} type 
         * @param {*} config 
         */
        const stats_summary = (svg, data, distr_types, type, config) => {
            let table_container = d3.select("#distribution-stats-" + type)
            table_container.selectAll("*").remove()

            let table = ""
            let columns = ""
            let thead = ""
            let tbody = ""
            let stats = {
                "mean": d3.mean,
                "variance": d3.variance,
                "deviation": d3.deviation,
                "min": d3.min,
                "max": d3.max,
            }

            let _stats = []
            let item = {}
            for (let type in distr_types) {
                for (let key in stats) {
                    item = {
                        ...item,
                        [key]: stats[key](data[type]).toFixed(2)
                    }
                }
                _stats.push(item)
            }

            table = table_container.append('table')
                .attr("width", width)
            columns = Object.keys(stats)
            thead = table.append("thead")
            tbody = table.append("tbody").attr("id", "stats-values")
            // append the header row
            thead.append("tr")
                .selectAll("th")
                .data(columns)
                .enter()
                .append("th")
                .text(function (column) { return column; });

            // create a row for each object in the data
            var rows = tbody.selectAll("tr")
                .data(_stats)
                .enter()
                .append("tr");

            // create a cell in each row for each column
            var cells = rows.selectAll("td")
                .data(function (row) {
                    return columns.map(function (column) {
                        return { column: column, value: row[column] };
                    });
                })
                .enter()
                .append("td")
                .attr("style", "font-family: Courier") // sets the font style
                .style("justify-content", "center")
                .html(function (d) {
                    return d.value;
                });


            if (type === "intervention") {
                let mean_diff = _stats[1]["mean"] - _stats[0]["mean"]
                let text = "A(n) " + req_object["intervention"]["type"] + " intervention on variable " + req_object["intervention"]["variable"] + " of value " + req_object["intervention"]["value"] + " caused the average of " + d3.select("#variable-select-" + type).property('value') + " to shift by " + (mean_diff.toFixed(2)).toString() + " units."
                let text_div = table_container.append("div")
                text_div.append("p").text(text).style("margin", "1em 0 0 0")
            }

        }
        svg_container.call(raincloud, data, distr_types, type, config, req_object)
    }

    /**
     * Initializes basic components of the model analysis container [1] treatment [2] outcome [3] stack container
     * @param {*} container 
     */
    async function fillModelAnalysisContainer(container) {
        let treatment = createSubContainer()
        $("<label />", {
            text: "Treatment"
        }).attr("width", "auto").attr("margin-left", "10px").attr("margin-top", "10px").appendTo(treatment)
        // Select option of treatement 
        $("<select />", {
            id: "model-analysis-treatment",
        }).attr("margin-left", "10px").appendTo(treatment)
        treatment.attr("id", "treatment-container")
        treatment.appendTo(container)
        let outcome = createSubContainer()
        outcome.attr("id", "outcome-container")
        outcome.appendTo(container)

        $("<label />", {
            text: "Outcome"
        }).attr("width", "auto").attr("margin-left", "10px").attr("margin-top", "10px").appendTo(outcome)
        $("<select />", {
            id: "model-analysis-outcome",
        }).attr("margin-left", "10px").appendTo(outcome)


        let pathStack = $("<div>", { class: "red-ui-sidebar-info-stack" });
        pathStack.appendTo(container)
        pathSections = RED.stack.create({
            id: "ma-paths-stack",
            container: pathStack
        })
        addModelAnalysisContainers(pathSections)
    }


