    async function addCausalAnalysisContainer(ca_stack, container_name) {
        let temp_section = ca_stack.add({
            title: causal_analysis_types[container_name].title,
            collapsible: true,
        })

        temp_section.content.css({
            "margin-top": "1em",
            "margin-bottom": "1em",
            "display": "flexbox",
        })
        temp_section.title.attr("id", "ca-" + container_name + "-title")
        temp_section.header.attr("id", "ca-" + container_name + "-header")
        temp_section.content.attr("id", "ca-" + container_name + "-content")
    }

    /**
     * Iterates through the causal inference analysis types to build the components for each section 
     * @param {object} causalAnalysisStack - node-red stack container to add various causal inference capabilities
     */
    async function initializeCausalAnalysisStrategies(causalAnalysisStack) {
        console.log("initializine causal anlaysis strategies")
        Object.keys(causal_analysis_types).forEach((container_name, index) => {
            console.log(causal_analysis_types[container_name])
            causalStrategyManager.addStrategy(new CausalAnalysisStrategy(container_name, causal_analysis_types[container_name]))
        })

        console.log(causalStrategyManager)

    }

    async function buildAnalysisCausalContainers(causalAnalysisStack) {
        Object.keys(causal_analysis_types).forEach(async (container_name, index) => {
            let strategy = causalStrategyManager.getStrategy(container_name)
            await addCausalAnalysisContainer(causalAnalysisStack, container_name)
            if (strategy !== undefined || strategy !== null) {
                strategy.build_container()
            }
        })
    }

